import json
from pathlib import Path


def add_matched_reader(w):
    p=Path(__file__).resolve().parents[1]/'swe_context'/'matched_reader'/'results.json'
    d=json.loads(p.read_text(encoding='utf8'))
    c=d['counts']
    w.page('SWE-ContextBench Lite  /  Два опыта с одним читателем',
           'Что меняется, если скрыть явные правки или заменить пятёрку кандидатов',
           'После основного результата зафиксировали две дополнительные проверки на тех же 99 задачах. Они уточняют механизм выбора прошлого опыта. Независимого подтверждения на новых задачах эти сравнения не дают.')
    w.p('В первом опыте у пяти исходных записей убирали поле с путями и идентификаторами из совершённых правок. Порядок кандидатов и остальной текст полностью сохранены. Объяснение агента и описание ошибки могли содержать те же сведения. Изменился и объём входа. Во втором опыте пять кандидатов выбирал авторский гибридный Recall. Содержание предложенных карточек, порядок по хешу и решатель Qwen3.8-27B остались общими.')
    arms=[('primary','Исходные кандидаты, полные записи'),('no_edits','Те же пять, без поля правок'),('recall_five','Пять из Recall, полные записи')]
    w.tbl(['Что видел читатель','Первый до Qwen','Эталон в 5','Первый после','Вход / выход, токены'],[
        [label,str(c[arm+'_retriever_1']),str(c[arm+'_top5']),str(c[arm+'_1']),
         w.n(d['costs'][arm]['input'])+' / '+w.n(d['costs'][arm]['output'])] for arm,label in arms
    ],[5.2,2.65,2.35,2.55,4.35],True)
    w.tbl(['Отличие от исходного','Выбор изменён','Исправлено / испорчено','Δ, п. п., 95% ДИ','p с поправкой'],[
        [label,str(c[arm+'_changed']),str(d['paired'][arm]['wins'])+' / '+str(d['paired'][arm]['losses']),
         w.pp(d['paired'][arm]['delta'],1)+' ('+w.pp(d['paired'][arm]['repo_ci95'][0],1)+' … '+w.pp(d['paired'][arm]['repo_ci95'][1],1)+')',w.dec(d['paired'][arm]['holm_p'],3)]
         for arm,label in arms[1:]
    ],[4.7,2.65,3.5,4.05,2.2],True)
    overlap=c['recall_five_overlap']/d['n']
    saved=d['costs']['primary']['input']-d['costs']['no_edits']['input']
    w.p(f"Если убрать поле правок, читатель меняет выбор всего для {c['no_edits_changed']} из {d['n']} вопросов. Это экономит {w.n(saved)} входных токенов, или {w.dec(100*saved/d['costs']['primary']['input'],1)}%. Разница в точности равна одной задаче. Остаётся проверить, можно ли показывать это поле только при затруднении и сохранить точность на новых задачах.")
    w.p(f"У исходного поиска и Recall средняя доля общих кандидатов составила {w.dec(overlap,2)} из 5. Состав пятёрки полностью совпал у {c['recall_five_same_set']} из {d['n']} задач. Это объясняет, сколько пространства для изменений получил один и тот же читатель. Recall использовал своё исходное представление и полный текст запроса.")
    w.p('Разница рассчитана как дополнительное условие минус исходное. Интервал получен при повторной выборке целых репозиториев. Для двух парных сравнений приведён двусторонний точный тест Мак-Немара с поправкой Холма. В стоимости учтены токены модели выбора. Расходы создания индекса и поиска до вызова модели сохранены отдельно.','Caption')
    w.source('Исходная реализация Recall и опубликованные метрики','https://github.com/alirng/recall/blob/585d0e21553d20e353588b9278e067d641a8283a/docs/benchmarks.md')

